using System.Windows;
namespace DomainConsole;
public partial class App : Application {
 protected override void OnStartup(StartupEventArgs e){base.OnStartup(e);if(e.Args.Contains("local-smoke")){StartupUri=null;ShutdownMode=ShutdownMode.OnExplicitShutdown;LocalSmoke();return;}DispatcherUnhandledException+=(s,a)=>{if(Environment.GetEnvironmentVariable("DOMAINCONSOLE_UI_SMOKE")=="1"){System.IO.File.WriteAllText(System.IO.Path.Combine(AppContext.BaseDirectory,"smoke-error.txt"),a.Exception.ToString());Shutdown(1);a.Handled=true;return;}MessageBox.Show(a.Exception.Message,"Domain Console");a.Handled=true;};}
 async void LocalSmoke(){var job=new DomainConsole.Shared.RemoteJob{Steps=new(){new(){Name="Local fixture",Kind="CMD",Code="echo LOCAL_TRANSPORT_OK"}}};var target=new DomainConsole.Shared.TargetRecord{Host=Environment.MachineName,Name=Environment.MachineName};job.Targets.Add(target);var service=new RemoteService();try{await service.Deploy(target,job);var until=DateTime.UtcNow.AddSeconds(45);while(DateTime.UtcNow<until){var result=await service.Poll(target,job.Id);if(result.State?.Status=="Completed"){if(!result.Output.Contains("LOCAL_TRANSPORT_OK"))throw new Exception("Local output lost.");var logs=await service.Logs(target,job.Id);if(!System.IO.Directory.GetFiles(logs,"*.out").Any())throw new Exception("Local log export failed.");System.IO.File.WriteAllText(System.IO.Path.Combine(AppContext.BaseDirectory,"local-smoke-ok.txt"),"Local SYSTEM deployment, result polling and log export passed.");Shutdown(0);return;}if(result.State?.Status=="Failed")throw new Exception(result.State.Error);await Task.Delay(500);}throw new TimeoutException("Local job did not finish.");}catch(Exception ex){System.IO.File.WriteAllText(System.IO.Path.Combine(AppContext.BaseDirectory,"local-smoke-error.txt"),ex.ToString());Shutdown(1);}finally{try{await PowerShellBridge.Execute("Unregister-ScheduledTask -TaskName "+PowerShellBridge.Literal("DomainConsoleCSharp-"+job.Id)+" -Confirm:$false -ErrorAction SilentlyContinue;Remove-Item (Join-Path (Join-Path $env:ProgramData 'DomainConsoleCSharp') "+PowerShellBridge.Literal(job.Id)+") -Recurse -Force -ErrorAction SilentlyContinue");}catch{}}}
}
